"""Renders RESULTS_B.md from results_b.json + profile_b.json (every number regenerated by one command)."""
import json, math
from pathlib import Path
from .injector import PTYPES, NAMES
H = Path(__file__).parent
r = json.loads((H / "results_b.json").read_text()); pr = json.loads((H / "profile_b.json").read_text())
T, hy = r["table"], r["hybrid"]
synthetic = r["source"].startswith("SYNTH")
f = lambda v: "-" if v is None else v
L = []
w = L.append
w("# RESULTS_B - Data-quality layer for NYC 311 (rules vs statistics vs LLM)\n")
w(f"**Data source of every number below:** {r['source']}\n")
if synthetic:
    w("> **WARNING - SYNTHETIC SMOKE RUN.** The build sandbox had no internet, so NYC Open Data could not be downloaded. These numbers prove the pipeline runs end-to-end on "
      "the 311 schema, **not** how the detectors behave on real 311 text. Synthetic text is templated, so near-100% detection and 0% false alarms are an artefact. "
      "Run `python run_all.py --fetch` on a networked machine to regenerate this file on real 2023 data.\n")
w(f"> Setup: batches of {r['batch_rows']} rows, {r['inject_rate']*100:.0f}% of rows corrupted (batch-level for schema/dtype/null-spike), {r['n_corrupt_per_type']} corrupted batches per type, "
  f"{r['n_clean']} clean batches for false alarms. Alert thresholds are calibrated on 10 separate clean batches (baseline count + 4 sigma + 2). CPU price assumed ${r['cpu_usd_per_hr_assumed']}/vCPU-hour (override `CPU_USD_PER_HR`). "
  "LLM column = NOT RUN unless `GEMINI_API_KEY` is set; its token volumes are projected from the real prompts.\n")
w("## 1. Real quality problems already in the data (Task 1)\n")
w(f"Profiled {pr['rows']:,} rows ({pr['source'][:40]}...). Full list: `project_b/profile_b.json`.\n")
w("| Problem | Rows | % | Example unique_keys |\n|---|---|---|---|")
for i in pr["issues"]:
    if i["count"]: w(f"| {i['issue']} | {i['count']:,} | {i['pct']}% | {', '.join(map(str, i['example_unique_keys']))} |")
if not any(i["count"] for i in pr["issues"]): w("| (none found) | 0 | 0 | |")
w("\n## 2. Per-problem detection, false alarms, cost (Tasks 3-4)\n")
w("Detect = % of corrupted batches alerted; FA = % of clean batches alerted; Rec = row-level recall; k rows/s measured in-process on this machine (batch-level schema checks are constant-time, shown capped); "
  "$/M = CPU dollars per million rows; Expl = explainability rubric 0-2 (2 = row evidence + expected value, 1 = batch-level metric, 0 = score only).\n")
w("| Problem | Rules: Detect/FA/Rec | Rules k rows/s, $/M, Expl | Stats: Detect/FA/Rec | Stats k rows/s, $/M, Expl | LLM (Gemini) | LLM projected tokens/M rows (sampled review) |\n|---|---|---|---|---|---|---|")
for p in PTYPES:
    a, b, l = T[p]["rules"], T[p]["stats"], T[p]["llm"]
    kr = lambda x: min(x["rows_per_s"] // 1000, 99999)
    llm_cell = "NOT RUN" if "detect_pct" not in l else f"{l['detect_pct']}/{l['false_alarm_pct']} (n={l['n_batches']})"
    w(f"| {NAMES[p]} | {a['detect_pct']}/{a['false_alarm_pct']}/{f(a['row_recall_pct'])} | {kr(a)}, {a['cpu_usd_per_M_rows']}, {a['explain_0_2']} | "
      f"{b['detect_pct']}/{b['false_alarm_pct']}/{f(b['row_recall_pct'])} | {kr(b)}, {b['cpu_usd_per_M_rows']}, {b['explain_0_2']} | {llm_cell} | {l['tokens_per_M_rows_batch_sampling']:,} |")
w(f"\nFull per-row LLM review of every row for ONE check would send about **{r['llm_full_per_row_tokens_per_M_rows_per_check']:,} input tokens per million rows** "
  f"(~{r['llm_row_tokens']} tokens/row) - x12 checks if each is a separate call. Multiply by your Gemini price (`GEMINI_PRICE_IN_PER_M`) for dollars; we do not assume a price.\n")
w("Reading the table (honest): rules and statistics tie on most types here; the clear separations are **null spike** (a rule on required columns only sees 4 of 5+ columns; the per-agency z-test sees any column) "
  "and **PII** (regex cannot see personal names, the shape heuristic can but would over-fire on real Title-Case free text - check FA on real data). "
  "Schema and dtype checks are set comparisons; the statistical family adds nothing there. Near-duplicates and ZIP/borough hinge on data: expect real data to show repeat-complaint false alarms for the near-dup rule.\n")
w("## 3. Hybrid pipeline (Task 5)\n")
w("Winner per type chosen automatically = max(detect - 2 x false-alarm), ties go to rules (cheaper, clearer alerts):\n")
w("| Problem | Chosen | Hybrid detect % (mixed batches) | n | Hybrid FA % (clean) |\n|---|---|---|---|---|")
for p in PTYPES:
    w(f"| {NAMES[p]} | {r['hybrid_choice'][p]} | {f(hy['per_type_detect_pct'][p])} | {hy['per_type_detect_n'][p]} | {hy['per_type_false_alarm_pct_on_clean'][p]} |")
w(f"\nEnd to end: **{hy['rows_per_s']:,} rows/s per core**, **${hy['cpu_usd_per_M_rows']} CPU per million rows**, any-alert false-alarm on clean batches **{hy['any_alert_on_clean_batch_pct']}%**, "
  f"LLM stage (second opinion on *alerted* semantic checks only, <=30 rows) projected **{hy['llm_confirm_tokens_per_M_rows_projected']:,} tokens per million rows** vs "
  f"{r['llm_full_per_row_tokens_per_M_rows_per_check']:,} for reviewing every row once. {hy['note']}\n")
rps = hy["rows_per_s"]; day = 50e6; avg = day / 86400; peak = avg * 5
w("## 4. Scale and design (Task 6) - 50M rows/day, 120 customers\n")
w(f"**Projection (from measured hybrid throughput, synthetic data, this machine; re-measure on yours):** average {avg:,.0f} rows/s, assumed 5x peak = {peak:,.0f} rows/s. "
  f"At {rps:,} rows/s/core that is **{max(1, math.ceil(peak / rps))} core(s) at peak** ({max(1, math.ceil(avg / rps))} on average); CPU cost/day = 50 x ${hy['cpu_usd_per_M_rows']} = **${50 * hy['cpu_usd_per_M_rows']:.3f}**. "
  f"A {r['batch_rows']}-row batch clears in ~{r['batch_rows'] / rps * 1000:.0f} ms. LLM confirmation tokens/day = 50 x {hy['llm_confirm_tokens_per_M_rows_projected']:,} = **{50 * hy['llm_confirm_tokens_per_M_rows_projected']:,} tokens** "
  f"(only if every batch alerted at today's rate); reviewing every row with an LLM = 50 x {r['llm_full_per_row_tokens_per_M_rows_per_check']:,} = **{50 * r['llm_full_per_row_tokens_per_M_rows_per_check']:,} tokens per check per day** - not viable.\n")
w("""**What changes at scale, and why**
1. *Schemas*: 120 customers means 120 column vocabularies. A per-customer column-mapping layer (declarative, versioned) replaces hard-coded names; an LLM may *propose* the mapping once at onboarding or on schema drift (rare, cheap, human-approved) - never per row.
2. *Reference statistics become per-customer state*: ZIP-borough map, pair/allow-list, per-agency null baselines, duration norms are fitted per customer, versioned, and refreshed on a schedule with drift alarms. This is where statistics beats hand-written rules: nobody curates 120 allow-lists.
3. *Curated rules shrink to universal invariants* (types, ISO dates, closed>=created, coordinate bounds, dup keys); everything customer-specific is learned. Near-duplicate and duplicate detection must become cross-batch (keyed store / Bloom filter + time window), because a 5k-row batch cannot see a duplicate that arrived an hour ago.
4. *Alert thresholds calibrated per customer* from their own clean baseline (as done here), otherwise the false-alarm rate on legitimately repetitive customers swamps the team.
5. *Engine*: in-process pandas is fine for 1-2 cores of average load, but 120 tenants and 5x peaks call for columnar/vectorised execution (Arrow/DuckDB or Polars), batching by tenant, and horizontal workers; CPU stays a rounding error, so the real cost drivers are people (false alarms) and LLM tokens.
6. *LLM budget*: second opinion only on alerted rows of semantic checks (pair, resolution, PII, ZIP), capped per customer per day, plus a small random audit sample to measure rule drift. Per-row review of every row is ~3 orders of magnitude more tokens than the hybrid and is not justified by any measurement here.
7. *Unknown unknowns*: one cheap profile-drift statistic per column (distribution shift) as a catch-all instead of 12 x 120 bespoke checks.

*Caveats:* synthetic text inflates detection; LLM detection was not run; throughput numbers are from a sandbox, not a laptop; cost excludes engineering and storage.
""")
(H.parent / "RESULTS_B.md").write_text("\n".join(L)); print("RESULTS_B.md written")
